from math import comb

def majority_probability(n: int, p: float) -> float:
    """Evaluate the strict-majority probability for positive odd n."""
    if n <= 0 or n % 2 == 0 or not 0.0 <= p <= 1.0:
        raise ValueError("require positive odd n and 0 <= p <= 1")
    return sum(comb(n, k) * p**k * (1-p)**(n-k)
               for k in range(n // 2 + 1, n + 1))

def symmetry_report(n: int, p: float) -> dict[str, float]:
    """Evaluate paired probabilities and their self-duality residual."""
    left = majority_probability(n, p)
    right = majority_probability(n, 1-p)
    return {"p": p, "C(p)": left, "C(1-p)": right,
            "residual": left + right - 1.0}

from collections.abc import Callable

def fair_point_bisection(crossing: Callable[[float], float],
                         tolerance: float = 1e-12) -> float:
    """Find the unique p with crossing(p)=1/2 for a monotone crossing function."""
    if tolerance <= 0:
        raise ValueError("tolerance must be positive")
    low, high = 0.0, 1.0
    while high - low > tolerance:
        mid = (low + high) / 2
        if crossing(mid) < 0.5:
            low = mid
        else:
            high = mid
    return (low + high) / 2
